mapper.sql:
h.status = 'APPROVED'

    AND (h.title LIKE CONCAT('%', #{keyword}, '%')
         OR h.city LIKE CONCAT('%', #{keyword}, '%')
         OR h.address LIKE CONCAT('%', #{keyword}, '%')
         OR h.description LIKE CONCAT('%', #{keyword}, '%'))


    AND h.city = #{city}


    AND h.type = #{type}


    AND h.price >= #{minPrice}


    AND h.price <= #{maxPrice}


    AND h.max_guests >= #{minGuests}


    AND NOT EXISTS (
        SELECT 1 FROM booking_order o
        WHERE o.homestay_id = h.id
          AND o.status IN ('PENDING_PAY', 'PAID', 'CHECKED_IN')
          AND o.check_in_date < #{checkOut}
          AND o.check_out_date > #{checkIn}
    )

